//! P6-M1-T02 integration tests: `oep-pmi` PMI model schema (GD&T, datums,
//! notes) and our-own-format serde serialization.
//!
//! The canonical example PMI document is byte-locked to the committed golden
//! `tests/golden/example-bracket.oeppmi.json` (generated by THIS crate via the
//! `OEP_PMI_REGEN=1` regen test), and independently re-parsed from the other
//! side by `tests/test_oep_pmi_acceptance.py` (stdlib Python). Two-sided: a
//! drift in either the serializer or the committed golden is caught here or
//! there.

use oep_pmi::{
    Characteristic, Datum, DatumFrame, DatumFrameRef, GeometricTolerance, MaterialCondition, Note,
    PmiDocument, ValidationError,
};

/// Path of the committed golden document (kept in sync with the acceptance
/// test's GOLDEN constant).
const GOLDEN_PATH: &str = "tests/golden/example-bracket.oeppmi.json";
const GOLDEN: &str = include_str!("golden/example-bracket.oeppmi.json");

/// Builds the canonical example: GD&T + datums + notes on the bracket product
/// (the same bracket whose geometry the oep-geo golden documents, P6-M1-T01).
/// The id references (features/bodies) match the oep-geo example ids so the
/// two documents compose at the importer hub.
pub fn build_example() -> PmiDocument {
    let mut doc = PmiDocument::new("mm");

    // Datums A, B, C designating bracket features.
    let datum_a = Datum::new("datum_A", "A").with_feature("oep-feature-bracket-extrude");
    let datum_b = Datum::new("datum_B", "B").with_feature("oep-feature-bracket-hole");
    let datum_c = Datum::new("datum_C", "C").with_feature("oep-feature-bracket-hole");
    for d in [&datum_a, &datum_b, &datum_c] {
        doc.push_datum(d.clone());
    }

    // Datum reference frame A|B|C.
    let drf = DatumFrame::new("drf_abc", "A-B-C")
        .with_ref(DatumFrameRef::new("datum_A", 1).with_modifier(MaterialCondition::Rfs))
        .with_ref(DatumFrameRef::new("datum_B", 2).with_modifier(MaterialCondition::Rfs))
        .with_ref(DatumFrameRef::new("datum_C", 3));
    doc.push_frame(drf);

    // GD&T on the bracket: position (diameter zone, MMC) on the mount holes
    // wrt A|B|C; flatness on the top face; perpendicularity of the holes.
    let pos = GeometricTolerance::new("gt_1", Characteristic::Position, 0.2)
        .with_diameter_zone(true)
        .with_material_condition(MaterialCondition::Mmc)
        .with_frame("drf_abc")
        .with_feature("oep-feature-bracket-hole");
    let flat = GeometricTolerance::new("gt_flat", Characteristic::Flatness, 0.05)
        .with_feature("oep-feature-bracket-extrude");
    let perp = GeometricTolerance::new("gt_perp", Characteristic::Perpendicularity, 0.1)
        .with_material_condition(MaterialCondition::Rfs)
        .with_frame("drf_abc")
        .with_feature("oep-feature-bracket-hole");
    for t in [&pos, &flat, &perp] {
        doc.push_tolerance(t.clone());
    }

    // Notes.
    let hole_note = Note::new("note_holes", "4X Ø6.00 THRU")
        .with_feature("oep-feature-bracket-hole")
        .with_position([40.0, 20.0, 0.0]);
    let units_note = Note::new("note_units", "ALL DIMENSIONS IN MM");
    doc.push_note(hole_note);
    doc.push_note(units_note);

    doc
}

// ---------------------------------------------------------------------------
// snapshot: the serializer is byte-locked to the committed golden
// ---------------------------------------------------------------------------

#[test]
fn serializer_snapshot_matches_committed_golden() {
    let text = build_example().to_json_pretty().expect("serialize");
    assert_eq!(text, GOLDEN, "serializer drifted from committed golden");
}

/// One-shot generator for the committed golden (run manually):
/// `OEP_PMI_REGEN=1 cargo test -p oep-pmi --test pmi_serde regenerate_golden`
#[test]
fn regenerate_golden() {
    match std::env::var("OEP_PMI_REGEN") {
        Ok(v) if v == "1" => {
            let text = build_example().to_json_pretty().expect("serialize");
            std::fs::write(GOLDEN_PATH, text).expect("write golden");
            eprintln!("wrote {GOLDEN_PATH}");
        }
        _ => eprintln!("skip: set OEP_PMI_REGEN=1 to (re)generate the golden"),
    }
}

// ---------------------------------------------------------------------------
// round-trip identity
// ---------------------------------------------------------------------------

#[test]
fn serialize_then_deserialize_is_identity() {
    let original = build_example();
    let text = original.to_json_pretty().expect("serialize");
    let back = PmiDocument::from_json_pretty(&text).expect("deserialize");
    assert_eq!(back, original);
}

#[test]
fn golden_roundtrips_and_validates_clean() {
    let doc = PmiDocument::from_json_pretty(GOLDEN).expect("parse committed golden");
    assert_eq!(doc.format(), "oep-pmi");
    assert_eq!(doc.version(), 1);
    assert_eq!(doc.units(), "mm");
    assert!(
        doc.validate().is_empty(),
        "unexpected issues: {:?}",
        doc.validate()
    );
}

// ---------------------------------------------------------------------------
// validation: each rule rejects a broken document
// ---------------------------------------------------------------------------

fn codes(errors: Vec<ValidationError>) -> Vec<&'static str> {
    let mut v: Vec<&'static str> = errors.iter().map(|e| e.code).collect();
    v.sort_unstable();
    v
}

#[test]
fn validate_rejects_duplicate_id() {
    let mut doc = build_example();
    doc.push_datum(Datum::new("datum_B", "D"));
    assert!(codes(doc.validate()).contains(&"duplicate-id"));
}

#[test]
fn validate_rejects_duplicate_label() {
    let mut doc = build_example();
    doc.push_datum(Datum::new("datum_X", "A")); // collides with datum_A's label
    assert!(codes(doc.validate()).contains(&"duplicate-label"));
}

#[test]
fn validate_rejects_unresolved_frame_datum() {
    let mut doc = build_example();
    doc.push_frame(
        DatumFrame::new("frame-ghost", "G-H").with_ref(DatumFrameRef::new("datum-not-there", 1)),
    );
    assert!(codes(doc.validate()).contains(&"unresolved-datum"));
}

#[test]
fn validate_rejects_unresolved_tolerance_frame() {
    let mut doc = build_example();
    doc.tolerances[0].frame_id = Some("frame-not-there".to_string());
    assert!(codes(doc.validate()).contains(&"unresolved-frame"));
}

#[test]
fn validate_rejects_invalid_and_duplicate_precedence() {
    let mut doc = build_example();
    doc.frames[0].refs[0].precedence = 9;
    assert!(codes(doc.validate()).contains(&"invalid-precedence"));

    let mut doc2 = build_example();
    doc2.frames[0].refs[0] = DatumFrameRef::new("datum_C", 3); // same as refs[2]
    assert!(codes(doc2.validate()).contains(&"duplicate-precedence"));
}

#[test]
fn validate_rejects_non_finite_tolerance_value() {
    let mut doc = build_example();
    doc.tolerances[0].value = f64::NAN;
    doc.tolerances[0].second_value = Some(-1.0);
    let c = codes(doc.validate());
    assert!(c.contains(&"non-finite-value"));
}

#[test]
fn validate_rejects_invalid_note_position() {
    let mut doc = build_example();
    doc.notes[0].position = Some([f64::NAN, 0.0, 0.0]);
    assert!(codes(doc.validate()).contains(&"invalid-position"));
}

// ---------------------------------------------------------------------------
// serialization shape (the documented our-own-format contract)
// ---------------------------------------------------------------------------

#[test]
fn header_and_collection_keys_serialize() {
    let doc = build_example();
    let val = serde_json::to_value(&doc).unwrap();
    assert_eq!(val["format"], "oep-pmi");
    assert_eq!(val["version"], 1);
    assert_eq!(val["units"], "mm");
    for col in ["datums", "frames", "tolerances", "notes"] {
        assert!(val[col].is_array(), "{col} must be an array");
    }
}

#[test]
fn material_condition_and_characteristic_serialize_kebab_case() {
    assert_eq!(serde_json::to_value(MaterialCondition::Mmc).unwrap(), "mmc");
    assert_eq!(serde_json::to_value(MaterialCondition::Rfs).unwrap(), "rfs");
    assert_eq!(
        serde_json::to_value(Characteristic::ProfileOfLine).unwrap(),
        "profile-of-line"
    );
    assert_eq!(
        serde_json::to_value(Characteristic::CircularRunout).unwrap(),
        "circular-runout"
    );
}

#[test]
fn tolerance_frame_ref_is_optional_in_json() {
    // A flatness tolerance (no frame, no modifier) omits the optional keys.
    let flat = GeometricTolerance::new("f1", Characteristic::Flatness, 0.05);
    let val = serde_json::to_value(&flat).unwrap();
    assert!(val.get("frame_id").is_none());
    assert!(val.get("material_condition").is_none());
}

#[test]
fn all_fourteen_characteristics_exist() {
    let all = [
        Characteristic::Straightness,
        Characteristic::Flatness,
        Characteristic::Circularity,
        Characteristic::Cylindricity,
        Characteristic::ProfileOfLine,
        Characteristic::ProfileOfSurface,
        Characteristic::Angularity,
        Characteristic::Perpendicularity,
        Characteristic::Parallelism,
        Characteristic::Position,
        Characteristic::Concentricity,
        Characteristic::Symmetry,
        Characteristic::CircularRunout,
        Characteristic::TotalRunout,
    ];
    assert_eq!(all.len(), 14);
    let serialized: Vec<String> = all
        .iter()
        .map(|c| serde_json::to_string(c).unwrap())
        .collect();
    assert!(serialized.iter().all(|s| s.starts_with('"')));
}
